setup:
MUTATE {
  CREATE CONCEPT ?ada { TYPE "Person" NAME "Ada" }
  CREATE CONCEPT ?grace { TYPE "Person" NAME "Grace" }
}

cases.command:
DEFINE PREDICATE "mentors" {
  description: "The subject mentors the object.",
  subject: {concept_types: ["Person"]},
  object: {concept_types: ["Person"]}
}

DEFINE CONCEPT TYPE "Instrument" {
  description: "A musical instrument.",
  attributes: {open: true, fields: {family: {type: "string", description: "strings, brass, percussion ..."}}}
}

MUTATE {
  CREATE CONCEPT ?violin { TYPE "Instrument" NAME "Violin" SET ATTRIBUTES {family: "strings"} }
}

DEFINE PREDICATE "main_instrument" {
  description: "The instrument the subject mainly plays.",
  subject: {concept_types: ["Person"]},
  object: {concept_types: ["Instrument"]},
  functional: true
}

MUTATE {
  CREATE CONCEPT ?cello { TYPE "Instrument" NAME "Cello" }
  ASSERT (:ada, "main_instrument", ?cello) {
    by: :ada, mode: "stated", at: "2026-09-01T00:00:00.000Z"
  }
}

DEFINE PREDICATE "prefers" {
  description: "already a Profile Predicate"
}

DEFINE PREDICATE "mentors" {
  description: "The subject mentors the object.",
  subject: {concept_types: ["Person"]},
  object: {concept_types: ["Person"]}
}

DEFINE CONCEPT TYPE "Person" {
  description: "another person"
}

DEFINE PREDICATE "closed_relation" {
  description: "authority over the data belongs to installed packages",
  open_world: false
}

DEFINE PREDICATE "exclusive_relation" {
  description: "one value excludes the others",
  functional: true,
  complete: true
}

DEFINE PREDICATE "unexplained" {
  subject: {concept_types: ["Person"]}
}

DEFINE PREDICATE "tagged" {
  description: "carries an unknown member",
  cardinality: 3
}

DEFINE CONCEPT TYPE "Genre" {
  description: "A musical genre.",
  attributes: {fields: {label: {type: "string", required: true}}}
}

DEFINE CONCEPT TYPE "Venue" {
  description: "A concert venue.",
  facets: {MnemonicState: {}}
}

MUTATE {
  DEFINE PREDICATE "inside" {description: "not a clause"}
}

MUTATE {
  CREATE CONCEPT ?type_review {
    TYPE "SleepTask" NAME "Review ConceptType Instrument"
    CLIENT KEY "review_schema:ConceptType:kip://local/draft@0.0.0/Instrument"
    SET ATTRIBUTES {task_class: "review_schema", summary: "ConceptType kip://local/draft@0.0.0/Instrument", status: "pending"}
  }
  CREATE CONCEPT ?predicate_review {
    TYPE "SleepTask" NAME "Review PredicateType Instrument"
    CLIENT KEY "review_schema:PredicateType:kip://local/draft@0.0.0/Instrument"
    SET ATTRIBUTES {task_class: "review_schema", summary: "PredicateType kip://local/draft@0.0.0/Instrument", status: "pending"}
  }
}

MUTATE {
  CREATE CONCEPT ?type_review {
    TYPE "SleepTask" NAME "Review ConceptType Instrument"
    CLIENT KEY "review_schema:ConceptType:kip://local/draft@0.0.0/Instrument"
    SET ATTRIBUTES {task_class: "review_schema", summary: "ConceptType kip://local/draft@0.0.0/Instrument", status: "pending"}
  }
  CREATE CONCEPT ?predicate_review {
    TYPE "SleepTask" NAME "Review PredicateType Instrument"
    CLIENT KEY "review_schema:PredicateType:kip://local/draft@0.0.0/Instrument"
    SET ATTRIBUTES {task_class: "review_schema", summary: "PredicateType kip://local/draft@0.0.0/Instrument", status: "pending"}
  }
}
